import { ArrowRight, BadgeDollarSign, Globe2, Headphones, Plane } from "lucide-react";
import TouristFooter from "../tourist/TouristFooter";
import TouristNavbar from "../tourist/TouristNavbar";

const services = [
  {
    icon: Plane,
    title: "Flight Booking",
    description: "Reservations across leading airlines with flexible travel dates and smooth ticket processing.",
  },
  {
    icon: Globe2,
    title: "Multiple Airlines",
    description: "Compare options from top international and regional carriers to match your route and budget.",
  },
  {
    icon: BadgeDollarSign,
    title: "Fare Options",
    description: "Choose from value, premium, and flexible pricing options tailored to your travel style.",
  },
  {
    icon: Headphones,
    title: "Booking Assistance",
    description: "Get dedicated support for itinerary changes, special requests, and quick travel guidance.",
  },
];

export default function ServicesPage() {
  return (
    <main className="min-h-screen bg-[#f8faff]">
      <TouristNavbar />

      <section id="services" className="pt-32 pb-20 bg-[#0f2557] relative overflow-hidden">
        <div className="absolute top-1/2 left-0 w-72 h-72 bg-[#f97316]/5 rounded-full blur-3xl" />
        <div className="absolute bottom-0 right-0 w-96 h-96 bg-blue-500/5 rounded-full blur-3xl" />

        <div className="max-w-7xl mx-auto px-4 relative z-10 text-center">
          <span className="inline-block text-[#f97316] text-sm font-semibold tracking-widest uppercase mb-3">
            Our Services
          </span>
          <h1 className="text-4xl md:text-6xl font-bold text-white font-heading mb-4">
            Flight Booking Services
          </h1>
          <p className="mx-auto max-w-2xl text-white/70 leading-relaxed">
            We make international travel easier with reliable booking support, airline comparisons, and flexible fare choices for every journey.
          </p>
          <div className="mt-8 flex justify-center">
            <a
              href="/#contact"
              className="inline-flex items-center gap-2 bg-[#f97316] hover:bg-[#ea6c0a] text-white font-semibold px-6 py-3 rounded-xl transition-all duration-200"
            >
              Plan Your Trip
              <ArrowRight size={16} />
            </a>
          </div>
        </div>
      </section>

      <section className="py-20 bg-[#f8faff]">
        <div className="max-w-7xl mx-auto px-4">
          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-6">
            {services.map(({ icon: Icon, title, description }) => (
              <div
                key={title}
                className="group rounded-3xl border border-[#e2e8f0] bg-white p-6 shadow-sm transition-all duration-300 hover:-translate-y-1 hover:shadow-xl"
              >
                <div className="mb-5 flex h-14 w-14 items-center justify-center rounded-2xl bg-[#0f2557] text-[#f97316] shadow-lg shadow-[#0f2557]/10 transition-colors group-hover:bg-[#f97316] group-hover:text-white">
                  <Icon size={24} />
                </div>

                <h2 className="mb-3 text-xl font-bold text-[#0f2557] font-heading">
                  {title}
                </h2>

                <p className="text-sm leading-relaxed text-neutral-600">
                  {description}
                </p>
              </div>
            ))}
          </div>
        </div>
      </section>

      <TouristFooter />
    </main>
  );
}
